import{_ as e,H as _,f as a,i as p}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"续写新篇：再启机器学习之旅","description":"","frontmatter":{},"headers":[],"relativePath":"机器学习40讲/续写新篇：再启机器学习之旅.md","filePath":"机器学习40讲/续写新篇：再启机器学习之旅.md","lastUpdated":1779820846000}'),r={name:"机器学习40讲/续写新篇：再启机器学习之旅.md"};function i(l,t,o,s,n,d){return _(),a("div",null,[...t[0]||(t[0]=[p('<h1 id="续写新篇-再启机器学习之旅" tabindex="-1">续写新篇：再启机器学习之旅 <a class="header-anchor" href="#续写新篇-再启机器学习之旅" aria-label="Permalink to &quot;续写新篇：再启机器学习之旅&quot;">​</a></h1><p>你好，我是王天一，好久不见！</p><p>近年来，机器学习领域在多个前沿方向上产生了不少积极的变化：小样本学习力图解决数据匮乏条件下学习性能的提升；可解释机器学习因复杂模型带来的不透明性愈发受到关注；跨模态学习通过实现不同模态数据间的信息深度融合，助力跨模态检索等任务；自动化机器学习则旨在学习“学习”的过程，从而提升学习效率，简化构建流程。</p><p>但就像我在专栏里说过的： <strong>再炫目的技术归根结底都是基本模型与方法在具体领域问题上的组合</strong>。以上提到的新进展其实都可以视为在新场景和新任务中对传统的学习方法进行优化，因此，持续夯实基础，大胆探索新路，依然是我们攀登技术高峰的必经之路。</p><p>基于此，我决定结合这几年的发展趋势，针对专栏中尚未涉及的新进展做一次补充和完善，与你分享我最近的感悟和认知。总的来说，我会补充以下内容（以实际上线为准）：</p><ul><li><p>小样本学习</p></li><li><p>可解释机器学习</p></li><li><p>跨模态学习</p></li><li><p>自动化机器学习</p></li></ul><p>如果你有更多想要了解的内容，也欢迎在留言区告诉我！</p>',7)])])}const m=e(r,[["render",i]]);export{f as __pageData,m as default};
